// The list of the rights of the guild ranks that scripts/gen-features.ts writes (#426).
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  generateGuildRights,
  GUILD_RIGHTS_DIR,
  GUILD_RIGHTS_FILE,
  renderGuildRights,
  scanGuildRights,
} from '../../scripts/gen-features.ts';

describe('the list of the rights of the guild ranks (#426)', () => {
  let dir: string;
  const HEADER =
    '// Generated by scripts/gen-features.ts; not checked in, do not edit.\n';
  const write = (file: string, source = 'export const guildRights = [];\n') => {
    mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });
    writeFileSync(path.join(dir, file), source);
  };

  beforeEach(() => {
    dir = path.join(mkdtempSync(path.join(tmpdir(), 'nova-')), 'guild-rights');
  });
  afterEach(() => rmSync(path.dirname(dir), { recursive: true, force: true }));

  it('is written before the tests run', () => {
    expect(
      readFileSync(path.join(GUILD_RIGHTS_DIR, GUILD_RIGHTS_FILE), 'utf8'),
    ).toBe(renderGuildRights(scanGuildRights(GUILD_RIGHTS_DIR)));
  });

  it('is empty but valid for an empty or missing folder', () => {
    expect(scanGuildRights(dir)).toEqual([]);
    expect(generateGuildRights(dir)).toBe(true);
    expect(readFileSync(path.join(dir, GUILD_RIGHTS_FILE), 'utf8')).toBe(
      `${HEADER}\nexport const GUILD_RIGHT_LISTS = [] as const;\n`,
    );
  });

  it('imports every file that exports guildRights, sorted, and writes only a change', () => {
    write('management.ts');
    write('chat.ts');
    write('other.ts', 'export const other = 1;\n');
    write('chat.test.ts');
    write(GUILD_RIGHTS_FILE);
    write('x.ts', 'export const myguildRights = [];\n');
    expect(scanGuildRights(dir)).toEqual(['chat.ts', 'management.ts']);
    expect(generateGuildRights(dir)).toBe(true);
    expect(generateGuildRights(dir)).toBe(false);
    expect(readFileSync(path.join(dir, GUILD_RIGHTS_FILE), 'utf8')).toBe(
      [
        HEADER,
        "import { guildRights as feature_chat } from './chat.ts';",
        "import { guildRights as feature_management } from './management.ts';",
        '',
        'export const GUILD_RIGHT_LISTS = [',
        "  ['chat', feature_chat],",
        "  ['management', feature_management],",
        '] as const;',
        '',
      ].join('\n'),
    );
  });
});
